1	export function checkEdict(chunkText, context) {
2	  // Bracketed markers only — see engine/mechanisms/veto.mjs for the full
3	  // rationale. "诏书" (edict) is the most common noun in a Tang governance
4	  // document; firing on it grants vetoImmunity, which disables the veto
5	  // mechanism, so a checks-and-balances regime would silently lose the very
6	  // behaviour under study the moment its offices' prose was captured.
7	  if (["[EDICT]", "[圣旨]", "[诏书]"].some((m) => String(chunkText ?? "").includes(m))) {
8	    if (!context.edictTriggered) {
9	      context.edictTriggered = true;
10	      console.error("\n[v6-Mechanism] IMPERIAL EDICT DETECTED! Overriding regular bureaucratic channels.");
11	      
12	      context.log.emit("edict_triggered", { 
13	        reason: "Absolute authority exercised to bypass standard procedures." 
14	      });
15	      
16	      // An edict might immune the process from vetoes for the remainder of the turn
17	      context.vetoImmunity = true;
18	      
19	      return true;
20	    }
21	  }
22	  return false;
23	}
